import { natalChart } from '@zodiacs/engine';
import { solarReturn, lunarReturn } from '@zodiacs/engine/techniques';
const natal = natalChart({
  utc: '2000-01-01T12:00:00Z', latitude: 51.4779,
  longitude: -0.0015, houseSystem: 'whole',
});
const solar = solarReturn(natal, '2026-01-01T12:00:00Z');
const lunar = lunarReturn(natal, '2026-03-20T12:00:00Z');
console.log({ solar: solar.instant.toISOString(), lunar: lunar.instant.toISOString() });

import { natalChart, synastry } from '@zodiacs/engine';
const first = natalChart({
  utc: '2000-01-01T12:00:00Z', latitude: 51.4779,
  longitude: -0.0015, houseSystem: 'whole',
});
const second = natalChart({
  utc: '2000-06-21T12:00:00Z', latitude: -33.8688,
  longitude: 151.2093, houseSystem: 'whole',
});
console.log(synastry(first, second));

import { searchLongitudeCrossings } from '@zodiacs/engine';
const result = searchLongitudeCrossings(
  'Mercury', 0, '2026-01-01T00:00:00Z', '2027-01-01T00:00:00Z',
  { stepDays: 1, maxSamples: 5000 },
);
if (result.status === 'refused') {
  console.log({ reason: result.reason, samples: result.samples });
} else {
  console.log(result.crossings.map(({ at, retrograde }) =>
    ({ utc: at.toISOString(), retrograde })));
}

import { calc } from '@zodiacs/engine/calc';
const result = calc({
  body: 'Sun', time: { jd: 2451545, scale: 'tt' },
  frame: 'ecliptic-true-of-date', center: 'geocentric',
  flags: { correction: 'apparent' },
  zodiac: { sidereal: 'lahiri' },
});
console.log(result);

import { calc } from '@zodiacs/engine/calc';
try {
  const result = calc({ body: 'Sun', time: '1700-06-01T12:00:00Z' });
  if (result.status === 'refused') {
    console.log({ reason: result.reason, detail: result.detail });
  }
} catch (error) {
  if (!(error instanceof RangeError)) throw error;
  console.log('Invalid input; correct the request before retrying.');
}

import { chart } from '@zodiacs/engine/calc';
const result = chart({
  time: '2000-01-01T12:00:00Z',
  place: { latitude: 51.4779, longitude: -0.0015 },
  houseSystem: 'whole',
});
if (result.status === 'ok') {
  const request = JSON.parse(JSON.stringify(result.receipt.request));
  const replayed = chart(request);
  console.log({ receipt: result.receipt, replayed });
} else {
  console.log({ reason: result.reason, detail: result.detail });
}

const request = {
  from: '2026-12-09T00:00:00Z',
  to: '2026-12-12T00:00:00Z',
  conditions: [
    { kind: 'phase', phase: 'waxing' },
    { kind: 'void-of-course', not: true },
    { kind: 'retrograde', body: 'Mercury', not: true },
    { kind: 'angular', body: 'Jupiter' },
  ],
  place: { latitude: 51.5072, longitude: -0.1276, houseSystem: 'placidus' },
};
const response = await fetch('https://zodiacs.org/api/v1/elections', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(request),
});
const result = await response.json();
if (!response.ok) throw new Error('The service refused this request: ' + response.status);
console.log(result);

const response = await fetch('https://zodiacs.org/api/v1/events', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    from: '2026-10-01T00:00:00Z',
    to: '2026-11-01T00:00:00Z',
    bodies: ['Sun', 'Mercury', 'Venus'],
    kinds: ['ingress', 'station', 'lunation'],
  }),
});
const answer = await response.json();
if (!response.ok) throw new Error(`The service refused this request: ${response.status} ${answer.error?.code}`);
for (const event of answer.result.events) console.log(event.at, event.kind, event.type ?? '', event.body ?? '', event.sign);
console.log(answer.backend.name, answer.backend.version, answer.cite.receipt);

const response = await fetch('https://zodiacs.org/api/v1/chart', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    local: { date: '1990-06-15', time: '14:30', zone: 'Europe/Paris' },
    latitude: 48.8566,
    longitude: 2.3522,
    houseSystem: 'whole',
  }),
});
const answer = await response.json();
if (!response.ok) throw new Error(`The service refused this request: ${response.status} ${answer.error?.code}`);
const { instant, local, bodies, angles } = answer.result;
console.log(instant, local.offsetMinutes, local.flags);
for (const { body, sign, degree } of bodies) console.log(body, sign, degree.toFixed(2));
console.log('Ascendant', angles.asc.toFixed(2));

import { natalChart } from '@zodiacs/engine';
const chart = natalChart({
  utc: '1990-06-15T12:30:00Z',
  latitude: 48.8566,
  longitude: 2.3522,
  houseSystem: 'placidus',
});
for (const { body, lon, retrograde } of chart.bodies) console.log(body, lon.toFixed(4), retrograde ? 'R' : '');
console.log(chart.houses.system, chart.houses.cusps.map((cusp) => cusp.toFixed(2)).join(' '));

import { positions } from '@zodiacs/engine';
for (const { body, lon, sign, retrograde } of positions('2026-10-12T00:00:00Z')) {
  console.log(body.padEnd(10), lon.toFixed(4), sign, retrograde ? 'retrograde' : '');
}

import { siderealChart, nakshatraOf } from '@zodiacs/engine/vedic';
const chart = siderealChart({
  utc: '2000-01-01T12:00:00Z',
  latitude: 28.6139,
  longitude: 77.209,
  houseSystem: 'whole',
}, 'lahiri');
const moon = chart.bodies.find(({ body }) => body === 'Moon');
const { name, pada, lord } = nakshatraOf(moon);
console.log('Lahiri', chart.ayanamsaValue.true.toFixed(4), 'Moon', moon.lon.toFixed(4), name, pada, lord);

import { Client, StreamableHTTPClientTransport } from '@modelcontextprotocol/client';
const client = new Client({ name: 'sky-check', version: '1.0.0' });
await client.connect(new StreamableHTTPClientTransport(new URL('https://zodiacs.org/mcp')));
try {
  const { tools } = await client.listTools();
  console.log(tools.map((tool) => tool.name));
  const fact = await client.callTool({
    name: 'check_sky_fact',
    arguments: { kind: 'retrograde', body: 'Mercury', instant: '2026-10-12T12:00:00Z' },
  });
  console.log(fact.structuredContent.data.answer);
} finally {
  await client.close();
}
